@Composable fun FlowBudgetTheme(store:FinanceStore,content:@Composable () -> Unit){var mode by remember{mutableStateOf(store.themeMode())};ThemeBus.mode=mode;ThemeBus.change={v->mode=v;store.setThemeMode(v)};val dark=when(mode){"DARK"->true;"LIGHT"->false;else->isSystemInDarkTheme()};val scheme=if(dark) darkColorScheme(primary=Color(0xFF58D6AE),secondary=Color(0xFFFFC857),background=Color(0xFF0B1412),surface=Color(0xFF14201D),onBackground=Color(0xFFE7F1EE),onSurface=Color(0xFFE7F1EE)) else lightColorScheme(primary=Emerald,secondary=Gold,background=Soft,surface=Color.White,onBackground=Navy,onSurface=Navy);MaterialTheme(colorScheme=scheme){content()}}
object ThemeBus{var mode:String="SYSTEM";var change:(String)->Unit={}}
@Composable fun FlowBudgetApp(store:FinanceStore){
 var route by remember{mutableStateOf("Home")};var refresh by remember{mutableIntStateOf(0)};var addNow by remember{mutableStateOf(false)};val tx=remember(refresh){store.transactions()};val premium=remember(refresh){store.premium()};if(!premium&&route=="Analyze")route="Plus";val inc=tx.filter{it.type==TxType.INCOME}.sumOf{it.amount};val exp=tx.filter{it.type==TxType.EXPENSE}.sumOf{it.amount}
 val nav=buildList{add("Home" to Icons.Default.Home);add("Activity" to Icons.Default.ReceiptLong);add("Banks" to Icons.Default.AccountBalance);add("Plan" to Icons.Default.EventNote);add("Goals" to Icons.Default.Savings);if(premium)add("Analyze" to Icons.Default.AutoGraph);add("Plus" to Icons.Default.Star)}
 Scaffold(containerColor=Color.Transparent,bottomBar={NavigationBar(containerColor=MaterialTheme.colorScheme.surface){nav.forEach{p->NavigationBarItem(selected=route==p.first,onClick={route=p.first},icon={Icon(p.second,null)},label={Text(p.first)})}}}){pad->Box(Modifier.padding(pad).fillMaxSize().background(Brush.verticalGradient(listOf(MaterialTheme.colorScheme.background,MaterialTheme.colorScheme.surface.copy(.94f),MaterialTheme.colorScheme.background)))){when(route){"Home"->Dashboard(store,inc,exp,tx,onAction={a->when(a){"Log expense"->addNow=true;"Plan bill"->route="Plan";"Goals"->route="Goals";"Bank statement"->route="Banks"}});"Activity"->Transactions(store,tx){refresh++};"Banks"->Banks(store){refresh++};"Plan"->FuturePlan(store,tx){refresh++};"Goals"->SavingsGoals(store){refresh++};"Analyze"->AnalyzePage(store,tx);else->PlusPage(store){refresh++}}}}
 if(addNow)AddDialog({addNow=false}){store.add(it);addNow=false;refresh++}
}
