approved bank(s)")}};AnimatedVisibility(importing){Text("Reading and organizing your bank alerts. You can stay on this page.",Modifier.padding(10.dp),color=MaterialTheme.colorScheme.primary)};AnimatedVisibility(success!=null){Card(Modifier.fillMaxWidth().padding(top=10.dp),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.primaryContainer),shape=RoundedCornerShape(16.dp)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.CheckCircle,null,tint=MaterialTheme.colorScheme.primary);Spacer(Modifier.width(10.dp));Text(success.orEmpty(),color=MaterialTheme.colorScheme.onPrimaryContainer,fontWeight=FontWeight.SemiBold)}}}}}}}
