@Composable fun AnalyzePage(store:FinanceStore,tx:List<Transaction>){
 var bank by remember{mutableStateOf("All accounts")};var period by remember{mutableStateOf("This month")};val cal=Calendar.getInstance();var month by remember{mutableIntStateOf(cal.get(Calendar.MONTH))};var year by remember{mutableIntStateOf(cal.get(Calendar.YEAR))}
 val accounts=listOf("All accounts")+tx.filter{it.bank!="Manual"}.map{it.bank+" "+it.account}.distinct();val filtered=SmartAnalyzer.filter(tx,bank,period,month,year);val cats=FlowIntelligence.categories(filtered);val total=cats.sumOf{it.second};val health=FlowIntelligence.health(filtered,store.budget());val subs=FlowIntelligence.subscriptions(filtered)
 LazyColumn(Modifier.fillMaxSize().padding(horizontal=18.dp)){
  item{Spacer(Modifier.height(16.dp));Title("Analytics","Patterns, predictions and spending distribution");PageHint("Filter by account and period. Analytics uses amounts, transaction categories and imported narration to summarize where money came from and what it was spent on.");Spacer(Modifier.height(10.dp));FilterMenu("Account",bank,accounts){bank=it};FilterMenu("Period",period,listOf("This month","Selected month","This year","All time")){period=it};if(period=="Selected month"){FilterMenu("Month",java.text.DateFormatSymbols().months[month],(0..11).map{java.text.DateFormatSymbols().months[it]}){month=java.text.DateFormatSymbols().months.indexOf(it)};FilterMenu("Year",year.toString(),(cal.get(Calendar.YEAR) downTo cal.get(Calendar.YEAR)-5).map{it.toString()}){year=it.toInt()}};Spacer(Modifier.height(10.dp));ElevatedCard(shape=RoundedCornerShape(24.dp)){Column(Modifier.padding(18.dp)){Text("Spending by category",fontWeight=FontWeight.Bold);DonutChart(cats,total);cats.take(6).forEachIndexed{i,p->CategoryBar(p.first,p.second,if(total>0)p.second/total else 0.0,i)}};Spacer(Modifier.height(14.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){StatCard("Health",health.score.toString()+"/100",Modifier.weight(1f));StatCard("Streak",health.streak.toString()+" days",Modifier.weight(1f));StatCard("Round-ups",money(FlowIntelligence.roundups(filtered)),Modifier.weight(1f))};Spacer(Modifier.height(14.dp));GlassCard{Text("Predictive bill runway",fontWeight=FontWeight.Bold);Text(FlowIntelligence.runway(filtered,store.futureExpenses()),color=MaterialTheme.colorScheme.onSurface.copy(.7f))};Spacer(Modifier.height(14.dp));Text("Smart insights",fontWeight=FontWeight.Bold);SmartAnalyzer.insights(filtered,store.budget()).forEach{PremiumCard(it.title,it.body,Icons.Default.AutoGraph)};Spacer(Modifier.height(12.dp));Text("Possible subscriptions",fontWeight=FontWeight.Bold);if(subs.isEmpty())Text("No recurring payment pattern is strong enough yet.",color=MaterialTheme.colorScheme.onBackground.copy(.6f))}
  }
  items(subs.take(8)){s->ElevatedCard(Modifier.fillMaxWidth().padding(vertical=5.dp),shape=RoundedCornerShape(18.dp)){ListItem(leadingContent={Icon(Icons.Default.Repeat,null,tint=MaterialTheme.colorScheme.primary)},headlineContent={Text(s.name,fontWeight=FontWeight.Bold)},supportingContent={Text(s.occurrences.toString()+" similar charges detected")},trailingContent={Text(money(s.amount),fontWeight=FontWeight.Bold)})}}
 }
}
@Composable fun DonutChart(cats:List<Pair<String,Double>>,total:Double){val colors=listOf(Color(0xFFFFA726),Color(0xFF2E7D32),Color(0xFF1E88E5),Color(0xFF8E24AA),Color(0xFFE53935),Color(0xFF00897B));Box(Modifier.fillMaxWidth().height(210.dp),contentAlignment=Alignment.Center){Canvas(Modifier.size(180.dp)){var start=-90f;cats.take(6).forEachIndexed{i,p->val sweep=if(total>0)(p.second/total*360).toFloat() else 0f;drawArc(colors[i%colors.size],start,sweep,false,style=Stroke(width=34f,cap=StrokeCap.Butt));start+=sweep}};Column(horizontalAlignment=Alignment.CenterHorizontally){Text("Total spent",color=MaterialTheme.colorScheme.onSurface.copy(.55f));Text(money(total),fontWeight=FontWeight.ExtraBold,style=MaterialTheme.typography.titleLarge)}}}
