@Composable fun FilterMenu(label:String,value:String,options:List<String>,select:(String)->Unit){var open by remember{mutableStateOf(false)};Box(Modifier.padding(vertical=5.dp)){OutlinedButton({open=true},shape=RoundedCornerShape(14.dp)){Text(label+": "+value);Icon(Icons.Default.ArrowDropDown,null)};DropdownMenu(open,{open=false}){options.forEach{o->DropdownMenuItem(text={Text(o)},onClick={select(o);open=false})}}}}
@Composable fun PremiumCard(t:String,s:String,i:androidx.compose.ui.graphics.vector.ImageVector){var open by remember{mutableStateOf(false)};ElevatedCard(Modifier.fillMaxWidth().padding(vertical=6.dp).clickable{open=true},shape=RoundedCornerShape(20.dp)){Row(Modifier.padding(18.dp),verticalAlignment=Alignment.CenterVertically){Icon(i,null,tint=Emerald,modifier=Modifier.size(30.dp));Spacer(Modifier.width(14.dp));Column{Text(t,fontWeight=FontWeight.Bold);Text(s,color=MaterialTheme.colorScheme.onSurface.copy(.62f))}}};if(open)InfoDialog(t,s){open=false}}

@Composable fun GlassCard(content:@Composable ColumnScope.()->Unit){ElevatedCard(Modifier.fillMaxWidth().animateContentSize(),shape=RoundedCornerShape(26.dp),colors=CardDefaults.elevatedCardColors(containerColor=MaterialTheme.colorScheme.surface)){Column(Modifier.padding(20.dp),content=content)}}
@Composable fun SavingsGoals(store:FinanceStore,changed:()->Unit){
 var show by remember{mutableStateOf(false)};val goals=store.savingsGoals()
 LazyColumn(Modifier.fillMaxSize().padding(18.dp)){
  item{Title("Savings Goals","Build envelopes for what matters next");PageHint("Create savings envelopes for future needs. Progress shows how much has been assigned toward each target.");Spacer(Modifier.height(10.dp));Button({show=true},shape=RoundedCornerShape(16.dp)){Icon(Icons.Default.Add,null);Text(" New goal")};Spacer(Modifier.height(14.dp))}
  items(goals){g->val p=if(g.target<=0)0f else (g.saved/g.target).toFloat().coerceIn(0f,1f);ElevatedCard(Modifier.fillMaxWidth().padding(vertical=6.dp),shape=RoundedCornerShape(22.dp)){Column(Modifier.padding(18.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(g.name,fontWeight=FontWeight.Bold);Text((p*100).toInt().toString()+"%")};Spacer(Modifier.height(10.dp));LinearProgressIndicator(progress={p},Modifier.fillMaxWidth().height(9.dp),strokeCap=StrokeCap.Round);Spacer(Modifier.height(8.dp));Text(money(g.saved)+" of "+money(g.target),color=MaterialTheme.colorScheme.onSurface.copy(.65f))}}}
 }
 if(show)GoalDialog({show=false}){g->store.addGoal(g);show=false;changed()}
}
@Composable fun GoalDialog(close:()->Unit,save:(SavingsGoal)->Unit){var n by remember{mutableStateOf("")};var t by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("New savings goal")},text={Column{OutlinedTextField(n,{n=it},label={Text("Goal name")});OutlinedTextField(t,{t=it},label={Text("Target amount")})}},confirmButton={Button({t.toDoubleOrNull()?.let{if(n.isNotBlank())save(SavingsGoal(name=n,target=it))}}){Text("Create")}},dismissButton={TextButton(close){Text("Cancel")}})}
@Composable fun FuturePlan(store:FinanceStore,tx:List<Transaction>,changed:()->Unit){
 val ctx=LocalContext.current;var show by remember{mutableStateOf(false)};val plans=store.futureExpenses();val accounts=listOf("All accounts")+tx.map{it.bank+" "+it.account}.distinct();val permission=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){}
 LaunchedEffect(Unit){FlowNotifications.ensure(ctx);if(android.os.Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(ctx,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)permission.launch(Manifest.permission.POST_NOTIFICATIONS)}
 LazyColumn(Modifier.fillMaxSize().padding(18.dp)){
  item{Title("Future spending","Plan ahead and let Flow Budget remind you");PageHint("Record upcoming bills and planned purchases. These entries power reminders and the Bill Runway forecast on your dashboard.");Spacer(Modifier.height(10.dp));Box(Modifier.fillMaxWidth().background(Brush.linearGradient(listOf(Color(0xFF183B56),Emerald)),RoundedCornerShape(28.dp)).padding(22.dp)){Column{Icon(Icons.Default.NotificationsActive,null,tint=Color.White);Text("Stay ahead of upcoming expenses",color=Color.White,fontWeight=FontWeight.Bold,style=MaterialTheme.typography.titleLarge);Text("Add bills, purchases, subscriptions or savings commitments and receive a reminder before they are due.",color=Color.White.copy(.8f));Spacer(Modifier.height(14.dp));Button({show=true}){Icon(Icons.Default.Add,null);Text(" Plan an expense")}}};Spacer(Modifier.height(18.dp));Text("Upcoming",fontWeight=FontWeight.Bold)}
  items(plans,key={it.id}){p->ElevatedCard(Modifier.fillMaxWidth().padding(vertical=6.dp),shape=RoundedCornerShape(20.dp)){ListItem(leadingContent={Icon(Icons.Default.Event,null,tint=Emerald)},headlineContent={Text(p.title,fontWeight=FontWeight.Bold)},supportingContent={Text(SmartAnalyzer.label(p.dueAt)+" • "+p.account+(if(p.reminder)" • Reminder on" else ""))},trailingContent={Column(horizontalAlignment=Alignment.End){Text(money(p.amount),fontWeight=FontWeight.Bold);IconButton({store.removeFuture(p.id);changed()}){Icon(Icons.Default.DeleteOutline,null)}}})}}
 }
 if(show)FutureDialog(accounts,{show=false}){future->store.addFuture(future);FlowNotifications.schedule(ctx,future);show=false;changed()}
}
@Composable fun FutureDialog(accounts:List<String>,close:()->Unit,save:(FutureExpense)->Unit){var title by remember{mutableStateOf("")};var amount by remember{mutableStateOf("")};var days by remember{mutableStateOf("7")};var account by remember{mutableStateOf("All accounts")};var reminder by remember{mutableStateOf(true)};AlertDialog(onDismissRequest=close,title={Text("Plan future spending")},text={Column{OutlinedTextField(title,{title=it},label={Text("What are you planning?")});OutlinedTextField(amount,{amount=it},label={Text("Amount (₦)")});OutlinedTextField(days,{days=it},label={Text("Due in how many days?")});FilterMenu("Account",account,accounts){account=it};Row(verticalAlignment=Alignment.CenterVertically){Switch(reminder,{reminder=it});Text(" Notify me one day before")}}},confirmButton={Button({val a=amount.toDoubleOrNull();val d=days.toIntOrNull();if(a!=null&&d!=null&&title.isNotBlank())save(FutureExpense(title=title,amount=a,dueAt=System.currentTimeMillis()+d*86400000L,account=account,reminder=reminder))}){Text("Save plan")}},dismissButton={TextButton(close){Text("Cancel")}})}

@Composable fun AppearanceCard(){val current=ThemeBus.mode;GlassCard{Row(verticalAlignment=Alignment.CenterVertically){Icon(if(current=="DARK")Icons.Default.DarkMode else Icons.Default.LightMode,null,tint=MaterialTheme.colorScheme.primary);Spacer(Modifier.width(10.dp));Column{Text("Appearance",fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.onSurface);Text("Choose how Flow Budget looks",color=MaterialTheme.colorScheme.onSurface.copy(.6f))}};Spacer(Modifier.height(10.dp));SingleChoiceSegmentedButtonRow(Modifier.fillMaxWidth()){listOf("SYSTEM" to "System","LIGHT" to "Light","DARK" to "Dark").forEachIndexed{i,p->SegmentedButton(selected=current==p.first,onClick={ThemeBus.change(p.first)},shape=SegmentedButtonDefaults.itemShape(i,3)){Text(p.second)}}}}}
